#include <bits/stdc++.h>
using namespace std;

#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops,fast-math")

const long long maxn = 21;
const long long mod = 1e9 + 7;

long long ans;
long long n, s;
long long a[maxn];
long long sum[1 << maxn];

void in();
void solve();
void out();
long long pwr(long long, long long);
long long C(long long, long long);

int main() {
    in();
    solve();
    out();
}

void in() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> s;
    for (long long i = 0; i < n; i++) {
        cin >> a[i];
        a[i]++;
    }
}

void solve() {
    for (long long i = 1; i < (1LL << n); i++) {
        sum[i] = sum[i - (i & -i)];
        sum[i] += a[__builtin_ctzll(i)];
    }

    for (long long i = 0; i < (1LL << n); i++) {
        long long term = C(s + n - 1 - sum[i], n - 1);
        if (__builtin_popcountll(i) & 1)
            ans = (ans - term + mod) % mod;
        else
            ans = (ans + term) % mod;
    }
}

void out() {
    cout << ans;
}

long long pwr(long long a, long long b) {
    if (b == 0)
        return 1;
    if (b < 0)
        return pwr(a, b + mod - 1);

    long long c = pwr(a, b / 2);
    if (b % 2)
        return c * c % mod * a % mod;
    return c * c % mod;
}

long long C(long long n, long long k) {
    if (n < k || n < 0 || k < 0)
        return 0;

    long long result = 1;
    for (long long i = 1; i <= k; i++) {
        result = result * pwr(i, -1) % mod;
        result = result * ((n - i + 1) % mod) % mod;
    }
    return result;
}

